INSERT INTO "Question" ("id", "prompt", "unit", "answer", "napkinMath", "sourceTitle", "sourceUrl", "source", "createdAt")
VALUES
  ('10000000-0000-4000-8000-000000000001', 'How many peanuts are produced worldwide each year?', 'PEANUTS', 62000000000, '~60 million tonnes harvested; unshelled beans run near 60 million per tonne.', 'Wikipedia: Peanut', 'https://en.wikipedia.org/wiki/Peanut', 'daily', CURRENT_TIMESTAMP),
  ('10000000-0000-4000-8000-000000000002', 'How many books are published worldwide each year?', 'BOOKS', 2500000, 'Roughly 2 million new titles per year across self-publishing and trade presses.', 'Wikipedia: Publishing', 'https://en.wikipedia.org/wiki/Publishing', 'daily', CURRENT_TIMESTAMP),
  ('10000000-0000-4000-8000-000000000003', 'How many cars are produced worldwide each year?', 'CARS', 93000000, 'Around 90 million in 2022; roughly 25 million in 1960.', 'Wikipedia: Automotive industry', 'https://en.wikipedia.org/wiki/Automotive_industry', 'daily', CURRENT_TIMESTAMP),
  ('10000000-0000-4000-8000-000000000004', 'How many coffee beans are grown worldwide each year?', 'COFFEE BEANS', 10000000, 'About 10 million tonnes of green coffee per year, roughly 60-70 kg per bag and 125 bags per tonne.', 'Wikipedia: Coffee production', 'https://en.wikipedia.org/wiki/Coffee_production', 'daily', CURRENT_TIMESTAMP),
  ('10000000-0000-4000-8000-000000000005', 'How many eyeglasses are made worldwide each year?', 'EYEGLASSES', 200000000, 'Vision needs affect about half of people; billions wear glasses already, with hundreds of millions added yearly.', 'Wikipedia: Glasses', 'https://en.wikipedia.org/wiki/Glasses', 'daily', CURRENT_TIMESTAMP),
  ('10000000-0000-4000-8000-000000000006', 'How many birds are killed by window strikes annually in North America?', 'BIRDS', 1000000000, 'Up to a billion birds die each year hitting windows in US and Canada.', 'Wikipedia: Bird strike', 'https://en.wikipedia.org/wiki/Bird_strike', 'daily', CURRENT_TIMESTAMP),
  ('10000000-0000-4000-8000-000000000007', 'How many kilograms of laundry are washed worldwide each day?', 'KG OF LAUNDRY', 2000000000, 'Billions of people, a few kilograms each, every single day.', 'Wikipedia: Washing machine', 'https://en.wikipedia.org/wiki/Washing_machine', 'daily', CURRENT_TIMESTAMP),
  ('10000000-0000-4000-8000-000000000008', 'How many cardboard boxes are used worldwide each year?', 'CARDBOARD BOXES', 100000000000, 'Corrugated packaging runs to tens of billions of tonnes of material a year.', 'Wikipedia: Corrugated box', 'https://en.wikipedia.org/wiki/Box', 'daily', CURRENT_TIMESTAMP),
  ('10000000-0000-4000-8000-000000000009', 'How many people watch the Super Bowl each year?', 'VIEWERS', 115000000, 'About 115 million viewers in recent years, a quarter of all US adults.', 'Wikipedia: Super Bowl', 'https://en.wikipedia.org/wiki/Super_Bowl', 'daily', CURRENT_TIMESTAMP),
  ('10000000-0000-4000-8000-000000000010', 'How many soccer goals are scored worldwide in a top-level league season?', 'GOALS', 25000, 'About 700-800 goals per league per season, across 20 clubs, each playing 38 matches.', 'Wikipedia: Association football', 'https://en.wikipedia.org/wiki/Association_football', 'daily', CURRENT_TIMESTAMP),
  ('10000000-0000-4000-8000-000000000011', 'How many tennis balls are used at Wimbledon each year?', 'TENNIS BALLS', 80000, 'Around 55,000 loose balls plus roughly 25,000 used in matches over the fortnight.', 'Wikipedia: Wimbledon', 'https://en.wikipedia.org/wiki/Wimbledon', 'daily', CURRENT_TIMESTAMP),
  ('10000000-0000-4000-8000-000000000012', 'How many tree seeds does a single large oak produce in a good year?', 'SEEDS', 700000, 'A mature oak drops around half a million acorns in a strong year, each holding one seed.', 'Wikipedia: Quercus robur', 'https://en.wikipedia.org/wiki/Quercus_robur', 'daily', CURRENT_TIMESTAMP),
  ('10000000-0000-4000-8000-000000000013', 'How many emails are sent worldwide each day?', 'EMAILS', 400000000000, 'Roughly 300-400 billion messages daily, most of them automated.', 'Wikipedia: Email', 'https://en.wikipedia.org/wiki/Email', 'daily', CURRENT_TIMESTAMP),
  ('10000000-0000-4000-8000-000000000014', 'How many ant species have been described so far?', 'ANT SPECIES', 14000, 'About 13,800-15,000 named species out of an estimated total well above that.', 'Wikipedia: Ant', 'https://en.wikipedia.org/wiki/Ant', 'daily', CURRENT_TIMESTAMP),
  ('10000000-0000-4000-8000-000000000015', 'How many hours of video are uploaded to the internet every minute?', 'MINUTES OF VIDEO', 500, 'Somewhere around 500 hours of new video every minute across major platforms.', 'Wikipedia: Web video', 'https://en.wikipedia.org/wiki/Online_video', 'daily', CURRENT_TIMESTAMP),
  ('10000000-0000-4000-8000-000000000016', 'How many ping-pong balls are used in one full table tennis match?', 'PING-PONG BALLS', 3, 'Best of five, so three games of one ball each.', 'Wikipedia: Table tennis', 'https://en.wikipedia.org/wiki/Table_tennis', 'daily', CURRENT_TIMESTAMP),
  ('10000000-0000-4000-8000-000000000017', 'How many slices of bread are eaten in the UK each day?', 'SLICES OF BREAD', 8000000, 'About 8 million loaves a day at roughly 500 grams and 30 slices per loaf.', 'Wikipedia: Bread', 'https://en.wikipedia.org/wiki/Bread', 'daily', CURRENT_TIMESTAMP),
  ('10000000-0000-4000-8000-000000000018', 'How many double-decker buses are in London?', 'BUSES', 13500, 'Around 13,500 buses, of which about 6,800 are double-deckers.', 'Transport for London', 'https://tfl.gov.uk/modes/buses', 'daily', CURRENT_TIMESTAMP),
  ('10000000-0000-4000-8000-000000000019', 'How many hot dogs are eaten in the United States each year?', 'HOT DOGS', 20000000000, 'About 20 billion, or roughly 7.7 per person per year.', 'Wikipedia: Hot dog', 'https://en.wikipedia.org/wiki/Hot_dog', 'daily', CURRENT_TIMESTAMP),
  ('10000000-0000-4000-8000-000000000020', 'How many trees are cut down worldwide each year for paper?', 'TREES', 4000000000, 'Around 4 billion trees a year for timber and paper production.', 'Wikipedia: Deforestation', 'https://en.wikipedia.org/wiki/Deforestation', 'daily', CURRENT_TIMESTAMP),
  ('10000000-0000-4000-8000-000000000021', 'How many people visit a typical major zoo each year?', 'VISITORS', 2500000, 'Large accredited zoos see 2-3 million visitors a year.', 'Wikipedia: Zoo', 'https://en.wikipedia.org/wiki/Zoo', 'daily', CURRENT_TIMESTAMP),
  ('10000000-0000-4000-8000-000000000022', 'How many ice cubes fit in a standard home freezer?', 'ICE CUBES', 700, 'A typical 200-litre freezer holds enough for a few trays plus loose cubes, roughly 700.', 'Wikipedia: Refrigerator', 'https://en.wikipedia.org/wiki/Refrigerator', 'daily', CURRENT_TIMESTAMP),
  ('10000000-0000-4000-8000-000000000023', 'How many drumsticks of chicken are eaten in the United States each year?', 'DRUMSTICKS', 10000000000, 'Around 10 billion a year at about 90 grams per drumstick.', 'Wikipedia: Chicken as food', 'https://en.wikipedia.org/wiki/Chicken_as_food', 'daily', CURRENT_TIMESTAMP),
  ('10000000-0000-4000-8000-000000000024', 'How many words does an average person speak each day?', 'WORDS', 16000, 'Around 16,000 spoken words per day, roughly 10 million over a lifetime.', 'Wikipedia: Speech', 'https://en.wikipedia.org/wiki/Speech', 'daily', CURRENT_TIMESTAMP),
  ('10000000-0000-4000-8000-000000000025', 'How many golf balls are hit in a single round of professional golf?', 'GOLF BALLS', 100, 'About 100 shots of 18 holes, and a new ball each time one is lost.', 'Wikipedia: Golf ball', 'https://en.wikipedia.org/wiki/Golf_ball', 'daily', CURRENT_TIMESTAMP),
  ('10000000-0000-4000-8000-000000000026', 'How many plastic bottles are produced worldwide each year?', 'PLASTIC BOTTLES', 9000000000, 'Roughly 9 billion single-use bottles a year globally.', 'Wikipedia: Plastic bottle', 'https://en.wikipedia.org/wiki/Plastic_bottle', 'daily', CURRENT_TIMESTAMP),
  ('10000000-0000-4000-8000-000000000027', 'How many piano keys are in a modern concert grand?', 'PIANO KEYS', 230, '88 keys, each spanning roughly 23.5 mm at the top end of the range.', 'Wikipedia: Grand piano', 'https://en.wikipedia.org/wiki/Grand_piano', 'daily', CURRENT_TIMESTAMP),
  ('10000000-0000-4000-8000-000000000028', 'How many ants are there for every human being on Earth?', 'ANTS PER PERSON', 2500000000, 'Estimates run to trillions of ants, on the order of 250 million per person.', 'Wikipedia: Ant', 'https://en.wikipedia.org/wiki/Ant', 'daily', CURRENT_TIMESTAMP),
  ('10000000-0000-4000-8000-000000000029', 'How many bananas are eaten worldwide each year?', 'BANANAS', 100000000000, 'About 100 billion bananas a year, on the order of 13 million tonnes.', 'Wikipedia: Banana', 'https://en.wikipedia.org/wiki/Banana', 'daily', CURRENT_TIMESTAMP),
  ('10000000-0000-4000-8000-000000000030', 'How many litres of blood does an average adult human body hold?', 'LITRES OF BLOOD', 5, 'Blood is about 8 percent of body weight; 70 kg gives roughly 5 litres.', 'Wikipedia: Blood', 'https://en.wikipedia.org/wiki/Blood', 'daily', CURRENT_TIMESTAMP);
